let brokers = msg.payload;

// se não tiver dados, responde com mensagem de erro
if (!brokers || !Array.isArray(brokers) || brokers.length === 0) {
    msg.headers = { 'content-type': 'text/html; charset=utf-8' };
    msg.payload = `<html><head><meta charset="utf-8"><title>Corretoras</title></head>
        <body><h2>Lista de corretoras</h2><p>Nenhuma corretora encontrada ou erro na API.</p></body></html>`;
    return msg;
}

let rows = brokers.map(b => {
    return `<li>${b.nome_social} - ${b.municipio} / ${b.cnpj}</li>`;
}).join('\n');

msg.headers = { 'content-type': 'text/html; charset=utf-8' };
msg.payload = `
<html>
<head>
  <meta charset="utf-8">
  <title>Corretoras CVM</title>
  <style>
    body{font-family:Arial,Helvetica,sans-serif;padding:20px}
    h1{color:#333}
    ul{list-style:none;padding:0}
    li{padding:6px 0;border-bottom:1px solid #eee}
  </style>
</head>
<body>
  <h1>Lista de Corretoras (CVM)</h1>
  <ul>${rows}</ul>
</body>
</html>`;
return msg;
